(function(){'use strict';var searchInput=document.getElementById('scSearchInput');var searchClear=document.getElementById('scSearchClear');var catSelect=document.getElementById('scCatSelect');var tableBody=document.getElementById('scTableBody');var statsEl=document.getElementById('scStats');var footerCountEl=document.getElementById('scFooterCount');function getCategories(){var cats=[];STATUS_CODES.forEach(function(item){if(cats.indexOf(item.category)===-1){cats.push(item.category);}});return cats;}function initCategorySelect(){var cats=getCategories();cats.forEach(function(cat){var opt=document.createElement('option');opt.value=cat;opt.textContent=cat;catSelect.appendChild(opt);});}function filterCodes(){var keyword=(searchInput.value||'').trim().toLowerCase();var selectedCat=catSelect.value;var filtered=STATUS_CODES.filter(function(item){if(selectedCat!=='all'&&item.category!==selectedCat){return false;}if(keyword){return item.name.toLowerCase().indexOf(keyword)!==-1||item.value.toLowerCase().indexOf(keyword)!==-1||item.description.toLowerCase().indexOf(keyword)!==-1||(item.solution&&item.solution.toLowerCase().indexOf(keyword)!==-1);}return true;});renderTable(filtered);}function renderTable(data){if(data.length===0){tableBody.innerHTML='<tr><td colspan="6" class="sc-empty">'+(typeof t==='function'?t('scNoMatch'):'😔 未找到匹配的状态码')+'</td></tr>';}else{var html='';data.forEach(function(item,index){var rowClass=item.value==='0x00000000'?'sc-row-success':'sc-row-error';var solutionText=item.solution||'';html+='<tr class="'+rowClass+'" data-name="'+item.name+'">'+'<td style="text-align:center">'+(index+1)+'</td>'+'<td><span class="sc-cat-tag sc-cat-'+getCategoryClass(item.category)+'">'+item.category+'</span></td>'+'<td class="sc-code-name">'+item.name+'</td>'+'<td class="sc-code-value">'+item.value+'</td>'+'<td>'+item.description+'</td>'+'<td class="sc-solution">'+solutionText+'</td>'+'</tr>';});tableBody.innerHTML=html;}var countText=data.length+'';if(typeof t==='function'){statsEl.textContent=t('scStats').replace('{n}',countText);footerCountEl.textContent=t('scCount').replace('{n}',countText);}else{statsEl.textContent='共 '+countText+' 条状态码';footerCountEl.textContent='共 '+countText+' 条';}}function getCategoryClass(category){if(category.indexOf('正确')!==-1)return 'success';if(category.indexOf('通用')!==-1)return 'general';if(category.indexOf('GenICam')!==-1)return 'genicam';if(category.indexOf('设备')!==-1)return 'device';if(category.indexOf('USB')!==-1||category.indexOf('U口')!==-1)return 'usb';if(category.indexOf('升级')!==-1)return 'upgrade';if(category.indexOf('网络')!==-1)return 'network';if(category.indexOf('IDMVS')!==-1)return 'idmvs';if(category.indexOf('读码器控制')!==-1)return 'control';if(category.indexOf('网口')!==-1)return 'ethernet';if(category.indexOf('底层')!==-1)return '底层';return 'default';}function onClearSearch(){searchInput.value='';searchInput.focus();filterCodes();}function onRowClick(e){var tr=e.target.closest('tr');if(!tr||!tr.dataset.name)return;var name=tr.dataset.name;if(navigator.clipboard){navigator.clipboard.writeText(name).then(function(){showToast('已复制:'+name);});}else{var textarea=document.createElement('textarea');textarea.value=name;document.body.appendChild(textarea);textarea.select();document.execCommand('copy');document.body.removeChild(textarea);showToast('已复制:'+name);}}function bindEvents(){var timer;searchInput.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(filterCodes,200);});searchClear.addEventListener('click',onClearSearch);catSelect.addEventListener('change',filterCodes);tableBody.addEventListener('click',onRowClick);}function init(){if(typeof STATUS_CODES==='undefined'){tableBody.innerHTML='<tr><td colspan="6" class="sc-empty">状态码数据未加载</td></tr>';return;}initCategorySelect();bindEvents();filterCodes();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();